        public static unsafe Matrix MatrixMultiply(Matrix a, Matrix b)
        {
            var o0 = Impl.NewMatrix(a.Rows, b.Cols);
            fixed (double* c_a_d = a.Data)
            fixed (double* c_b_d = b.Data)
            fixed (double* p0 = o0.Data)
            {
                var c_a = Impl.View(a, c_a_d);
                var c_b = Impl.View(b, c_b_d);
                Impl.Check(Native.rant_matrix_multiply(c_a, c_b, new RawMatrixView { data = p0, rows = o0.Rows, cols = o0.Cols }));
                return o0;
            }
        }

