        /// <summary>x such that a x = b, each column of b solved alone. With more rows than columns, the x with the
        /// least squared error. Fails when the columns of a are dependent.</summary>
        public static unsafe Matrix MatrixSolve(Matrix a, Matrix b)
        {
            var o0 = Impl.NewMatrix(a.Cols, b.Cols);
            fixed (double* c_a_d = a.Data)
            fixed (double* c_b_d = b.Data)
            fixed (double* p0 = o0.Data)
            {
                var c_a = Impl.View(a, c_a_d);
                var c_b = Impl.View(b, c_b_d);
                Impl.Check(Native.rant_matrix_solve(c_a, c_b, new RawMatrixView { data = p0, rows = o0.Rows, cols = o0.Cols }));
                return o0;
            }
        }

        /// <summary>a = u diag(s) v^T for an m by n matrix and k = min(m, n): u is m by k, s holds k values from the
        /// largest down, v is n by k.</summary>
        public static unsafe (Matrix U, double[] S, Matrix V) MatrixSvd(Matrix a)
        {
            var o0 = Impl.NewMatrix(a.Rows, System.Math.Min(a.Rows, a.Cols));
            var o1 = new double[System.Math.Min(a.Rows, a.Cols)];
            var o2 = Impl.NewMatrix(a.Cols, System.Math.Min(a.Rows, a.Cols));
            fixed (double* c_a_d = a.Data)
            fixed (double* p0 = o0.Data)
            fixed (double* p1 = o1)
            fixed (double* p2 = o2.Data)
            {
                var c_a = Impl.View(a, c_a_d);
                Impl.Check(Native.rant_matrix_svd(c_a, new RawMatrixView { data = p0, rows = o0.Rows, cols = o0.Cols }, p1, new RawMatrixView { data = p2, rows = o2.Rows, cols = o2.Cols }));
                return (o0, o1, o2);
            }
        }

        /// <summary>A symmetric matrix's eigenvalues from the smallest up, each eigenvector a column.</summary>
        public static unsafe (double[] Values, Matrix Vectors) MatrixEigen(Matrix a)
        {
            var o0 = new double[a.Rows];
            var o1 = Impl.NewMatrix(a.Rows, a.Rows);
            fixed (double* c_a_d = a.Data)
            fixed (double* p0 = o0)
            fixed (double* p1 = o1.Data)
            {
                var c_a = Impl.View(a, c_a_d);
                Impl.Check(Native.rant_matrix_eigen(c_a, p0, new RawMatrixView { data = p1, rows = o1.Rows, cols = o1.Cols }));
                return (o0, o1);
            }
        }

        /// <summary>The lower l with a = l l^T. Fails when a is not symmetric positive definite.</summary>
        public static unsafe Matrix MatrixCholesky(Matrix a)
        {
            var o0 = Impl.NewMatrix(a.Rows, a.Cols);
            fixed (double* c_a_d = a.Data)
            fixed (double* p0 = o0.Data)
            {
