        /// <summary>The points keep marks with 1, whole and in order, into data at point_step bytes each.</summary>
        public static unsafe PointCloud PointCloudSelect(PointCloud cloud, ReadOnlySpan<byte> keep)
        {
            using (var p = new CloudPin(cloud))
            fixed (byte* k = keep)
            {
                var c = p.Raw;
                Impl.Check(Native.rant_point_cloud_check(&c));
                if ((ulong)keep.Length != (ulong)c.size / c.point_step) throw new MathException(ErrorKind.Argument);
                uint n = 0;
                Impl.Room(Native.rant_point_cloud_select(&c, k, null, &n));
                var data = new byte[(int)n * (int)c.point_step];
                fixed (byte* d = data) Impl.Check(Native.rant_point_cloud_select(&c, k, d, &n));
                var r = Impl.CloudLike(c);
                r.Data = data;
                return r;
            }
        }

